{
    [LoggerMessage(Level = LogLevel.Debug, Message = "AI summary failed for {File}, falling back to static extraction")]
    private static partial void LogAiSummaryFailed(ILogger logger, Exception ex, string file);

    private static readonly HashSet<string> AiSummaryExtensions = new(StringComparer.OrdinalIgnoreCase)
    {
        ".cs", ".ts", ".tsx", ".js", ".jsx", ".py", ".go", ".rs", ".cpp", ".c", ".h",
        ".fs", ".vb", ".swift", ".kt", ".java"
    };

    private readonly ILogger<AiSummarizationService> _logger;
    private readonly ICodeSummarizer? _summarizer;

    public AiSummarizationService(ILogger<AiSummarizationService> logger, ICodeSummarizer? summarizer = null)
    {
        _logger = logger;
        _summarizer = summarizer;
    }

    public async Task<string> GetFileDescriptionAsync(string absPath, string relPath, string ext,
        SemaphoreSlim aiThrottle, bool preferBackupEndpoint, CancellationToken ct)
    {
        if (_summarizer != null && AiSummaryExtensions.Contains(ext))
        {
            try
            {
                const int maxInput = 4096;
                await using FileStream fs = new(absPath, FileMode.Open, FileAccess.Read, FileShare.Read);
                byte[] buf = new byte[maxInput];
                int read = await fs.ReadAsync(buf.AsMemory(0, maxInput), ct);
                string text = Encoding.UTF8.GetString(buf, 0, read);
                string hash = WorkspaceIndexDbAccessor.ComputeHash(text);

                await aiThrottle.WaitAsync(ct);
                try
                {
                    string? summary = await _summarizer.SummarizeAsync(
                        text, Path.GetFileName(absPath), hash, preferBackupEndpoint, ct);
                    if (!string.IsNullOrWhiteSpace(summary))
                    {
                        return summary;
                    }
                }
                finally
                {
                    _ = aiThrottle.Release();
                }
            }
            catch (Exception ex)
            {
                LogAiSummaryFailed(_logger, ex, relPath);
            }
        }

        return await StaticFileSummarizer.ExtractAsync(absPath) ?? Path.GetFileName(relPath);
    }
}

internal static class CodeParserUtils
{
    /// <summary>
    ///     Starting at <paramref name="startIndex" /> (on or just before the opening '{'),
    ///     finds the matching closing '}' and returns the content between braces.
    ///     Returns null if the block exceeds <paramref name="maxChars" /> or is not found.
    /// </summary>
    public static string? ExtractBraceBlock(string source, int startIndex, int maxChars = 5000)
    {
        int depth = 0;
        int start = -1;

        for (int i = startIndex; i < Math.Min(source.Length, startIndex + maxChars); i++)
        {
            switch (source[i])
            {
                case '{':
                    if (start < 0)
                    {
                        start = i;
                    }

                    depth++;
                    break;
                case '}':
                    depth--;
                    if (depth == 0 && start >= 0)
                    {
                        string inner = source[(start + 1)..i].Trim();
                        return inner.Length > maxChars ? null : inner;
                    }

                    break;
            }
        }

        return null;
    }

    /// <summary>
    ///     Extracts the first line of an XML <c>&lt;summary&gt;</c> doc comment immediately
    ///     preceding the given <paramref name="position" /> in the source.
    ///     Returns null if none found within the previous 8 lines.
    /// </summary>
    public static string? ExtractXmlSummary(string source, int position)
    {
        string before = source[..position];
        string[] lines = before.Split('\n');
        for (int i = lines.Length - 1; i >= Math.Max(0, lines.Length - 8); i--)
        {
            string line = lines[i].Trim();
            if (line.StartsWith("/// <summary>", StringComparison.Ordinal))
            {
                string summary = line.Replace("/// <summary>", "", StringComparison.Ordinal).Replace("</summary>", "", StringComparison.Ordinal).Trim();
                if (summary.Length > 0)
                {
                    return summary;
                }
            }
        }

        return null;
    }

    /// <summary>
    ///     Stable, non-cryptographic id from file path + symbol name + line number.
    ///     Not used for security purposes — only for deterministic symbol identity in the index.
    ///     Uses SHA-256 (truncated) purely because it's a convenient, collision-resistant,
    ///     built-in stable hash; no cryptographic guarantee is required or relied upon here.
    /// </summary>
    public static string MakeId(string filePath, string name, int line)
    {
        string input = $"{filePath}|{name}|{line}";
        byte[] hash = SHA256.HashData(Encoding.UTF8.GetBytes(input));
        return Convert.ToHexString(hash)[..16].ToUpperInvariant();
    }
}

