                join s2 in ctx.Symbols on r.TargetSymbolId equals s2.Id
                where s2.File!.RelativePath == filePath && s1.File!.RelativePath != filePath
                select s1.File!.RelativePath
            ).Distinct().Take(100).ToListAsync(ct),
            ct);
    }
