        [
            "fix", "error", "exception", "crash", "stack trace", "why is", "not working", "fails", "failure", "broken"
        ]),
        (TaskType.Test,
            ["test", "spec", "assert", "mock", "coverage", "unit test", "integration test", "xunit", "nunit"]),
        (TaskType.Refactor,
            ["refactor", "extract", "clean up", "cleanup", "rename", "reorganize", "restructure", "move"]),
        (TaskType.Review, ["review", "look at", "check", "what do you think", "feedback", "critique"]),
        (TaskType.Explain, ["explain", "how does", "what is", "walk me through", "describe", "understand"]),
        (TaskType.Planning, ["plan", "design", "architecture", "approach", "strategy", "how should", "where should"]),
        (TaskType.Code, ["write", "implement", "add", "create", "build", "generate", "make"])
    ];
    private static readonly Regex FilePathRegex = new(
        @"(?:`([^`]+)`|(\S+?(?:\.cs|\.json|\.md|\.ts|\.js|\.py|\.yaml|\.yml|\.xml|\.csproj|\.slnx|\.sln|\.txt|\.config)))",
        RegexOptions.Compiled | RegexOptions.IgnoreCase);

    private static readonly Regex ConstraintRegex = new(
        @"(?:don'?t|do not|never|keep|preserve|leave|avoid)\s+(.{5,60}?)(?:[,.]|$)",
        RegexOptions.Compiled | RegexOptions.IgnoreCase);

    private readonly ContextHelperConfig _config = config.Value;

    public async Task<PromptAssessment> AssessAsync(string prompt, string[]? history, CancellationToken ct = default)
    {
        string combined = string.Join(" ", (history ?? []).TakeLast(2).Append(prompt));

        (TaskType taskType, double confidence) = ClassifyByKeywords(combined);
        LogTier1Classified(logger, taskType, confidence);

        if (confidence < _config.PromptAssessorConfidenceThreshold)
        {
            TaskType? modelType = await ClassifyByModelAsync(prompt, ct);
            if (modelType.HasValue)
            {
                taskType = modelType.Value;
                confidence = 0.8;
                LogTier2Reclassified(logger, taskType);
            }
        }

        return new PromptAssessment
        {
            TaskType = taskType,
            WeightProfile = _config.GetWeightProfile(taskType),
            KeyFiles = ExtractKeyFiles(combined),
            Constraints = ExtractConstraints(combined),
            KeyConcepts = ExtractKeyConcepts(prompt),
            Confidence = confidence
        };
    }

    // ── Tier 1: keyword matching ───────────────────────────────────────────────

    private static (TaskType Type, double Confidence) ClassifyByKeywords(string text)
    {
        Dictionary<TaskType, int> scores = [];

        foreach ((TaskType type, string[]? keywords) in Patterns)
        {
            int hits = keywords.Count(k => text.Contains(k, StringComparison.OrdinalIgnoreCase));
            if (hits > 0)
            {
                scores[type] = hits;
            }
        }

        if (scores.Count == 0)
        {
            return (TaskType.General, 0.3);
        }

        KeyValuePair<TaskType, int> best = scores.MaxBy(kv => kv.Value);
        int total = scores.Values.Sum();
        double conf = Math.Min(0.95, ((double)best.Value / total) + 0.2);
        return (best.Key, conf);
    }

    // ── Tier 2: model fallback ─────────────────────────────────────────────────

    private async Task<TaskType?> ClassifyByModelAsync(string prompt, CancellationToken ct)
    {
        try
        {
            string classifyPrompt =
                $"""
                 Classify this prompt into exactly one category. Reply with only the category name.
                 Categories: Code, Debug, Planning, Review, Explain, Refactor, Test, General

                 Prompt: {prompt}

                 Category:
                 """;

            var payload = new { model = "HelperModel", prompt = classifyPrompt, stream = false };
            HttpResponseMessage response = await http.PostAsJsonAsync("/api/generate", payload, ct);
            if (!response.IsSuccessStatusCode)
            {
                return null;
            }

            GenerateResponse? result = await response.Content.ReadFromJsonAsync<GenerateResponse>(ct);
            string text = result?.Response?.Trim() ?? "";
            return Enum.TryParse<TaskType>(text, true, out TaskType parsed) ? parsed : null;
        }
        catch (Exception ex)
        {
            LogTier2CallFailed(logger, ex);
            return null;
        }
    }

    // ── Extraction helpers ─────────────────────────────────────────────────────

    private static string[] ExtractKeyFiles(string text)
    {
        MatchCollection matches = FilePathRegex.Matches(text);
        return [.. matches
            .Select(m => (m.Groups[1].Success ? m.Groups[1].Value : m.Groups[2].Value).Trim())
            .Where(f => !string.IsNullOrEmpty(f))
            .Distinct(StringComparer.OrdinalIgnoreCase)];
    }

public partial class StrippingHealthAnalyzer
{
    [LoggerMessage(Level = LogLevel.Information, Message = "StrippingHealth: {Reason}")]
    private static partial void LogStrippingHealthReason(ILogger logger, string reason);

    private readonly ContextHelperConfig _config;
    private readonly ILogger<StrippingHealthAnalyzer> _logger;

    public StrippingHealthAnalyzer(IOptions<ContextHelperConfig> config, ILogger<StrippingHealthAnalyzer> logger)
    {
        _config = config.Value;
        _logger = logger;
    }

    /// <summary>
    ///     Analyses signals and returns an adjustment overlay plus a human-readable warning
    ///     if over-stripping is detected (null warning = healthy).
    /// </summary>
    public (StrippingAdjustment Adjustment, string? Warning) Analyze(
        SessionSignals signals, int tokenBudget)
    {
        int? collapseThreshold = null;
        double? semanticThreshold = null;
        int? verbatimTurns = null;
        List<string> reasons = [];

        if (signals.GetCodeBlockCalls > 2)
        {
            collapseThreshold = _config.CodeBlockCollapseThreshold + 20;
            reasons.Add($"GetCodeBlock called {signals.GetCodeBlockCalls}× — raising collapse threshold by 20 lines");
        }

        if (signals.RebuildContextCalls > 1)
        {
            semanticThreshold = Math.Max(0.1, _config.SemanticThreshold - 0.05);
            reasons.Add(
                $"Context rebuilt {signals.RebuildContextCalls}× for same files — lowering semantic threshold by 0.05");
        }

        if (signals.TurnsWithFileRequests > _config.VerbatimTurns)
        {
            verbatimTurns = _config.VerbatimTurns + 2;
            reasons.Add(
                $"Model requested already-seen files in {signals.TurnsWithFileRequests} turns — increasing verbatim window by 2");
        }

        double wasteRatio = tokenBudget > 0 ? signals.EstimatedWastedTokens / tokenBudget : 0;
        string? warning = null;

        if (reasons.Count > 0 || wasteRatio > _config.OverStrippingWasteRatioThreshold)
        {
            string wastedStr = signals.EstimatedWastedTokens > 0
                ? $" (estimated {(int)signals.EstimatedWastedTokens:N0} wasted tokens on re-fetches)"
                : "";
            warning =
                $"ℹ️ Context health: stripping thresholds may be too aggressive this session{wastedStr}. " +
                $"Thresholds relaxed for this build.";

            foreach (string r in reasons)
            {
                LogStrippingHealthReason(_logger, r);
            }
        }

        return (new StrippingAdjustment(collapseThreshold, semanticThreshold, verbatimTurns), warning);
    }

    /// <summary>
    ///     Records a GetCodeBlock call against a session's signals.
    /// </summary>
    public static void RecordCodeBlockRequest(SessionSignals signals)
    {
        signals.GetCodeBlockCalls++;
        signals.LastUpdated = DateTimeOffset.UtcNow;
    }

    /// <summary>
    ///     Records that context was rebuilt for an already-seen set of files.
    /// </summary>
    public static void RecordContextRebuild(SessionSignals signals, int wastedTokens = 0)
    {
        signals.RebuildContextCalls++;
        signals.EstimatedWastedTokens += wastedTokens;
        signals.LastUpdated = DateTimeOffset.UtcNow;
    }
}

public static void RecordCodeBlockRequest(SessionSignals signals)
{
    signals.GetCodeBlockCalls++;
    signals.LastUpdated = DateTimeOffset.UtcNow;
}

public static void RecordContextRebuild(SessionSignals signals, int wastedTokens = 0)
{
    signals.RebuildContextCalls++;
    signals.EstimatedWastedTokens += wastedTokens;
    signals.LastUpdated = DateTimeOffset.UtcNow;
}

public partial class DeduplicationStage : IPipelineStage
{
    [LoggerMessage(Level = LogLevel.Warning, Message = "Spaghetti code detected: {Count} near-duplicate blocks in {File}")]
    private static partial void LogSpaghettiDetected(ILogger logger, int count, string file);

    [LoggerMessage(Level = LogLevel.Debug, Message = "{Stage}: saved {Saved} tokens in {Ms}ms")]
    private static partial void LogStageSavings(ILogger logger, string stage, int saved, long ms);

    private readonly ContextHelperConfig _config;
    private readonly ILogger<DeduplicationStage> _logger;

    public DeduplicationStage(IOptions<ContextHelperConfig> config, ILogger<DeduplicationStage> logger)
    {
        _config = config.Value;
        _logger = logger;
    }

    public string Name => "Deduplication";

    public async Task<PipelineContext> ProcessAsync(PipelineContext ctx, CancellationToken ct = default)
    {
        Stopwatch sw = Stopwatch.StartNew();
        StageDiagnostic diag = new() { StageName = Name, InputTokens = ctx.EstimateTokens() };

        int collapsed = 0, dropped = 0;
        Dictionary<string, List<string>> fileBlockCounts = []; // source → block hashes
        List<string> notes = [];

        // Process history turns in parallel
        string[] processed = new string[ctx.History.Count];
        await Parallel.ForEachAsync(
            Enumerable.Range(0, ctx.History.Count),
            PipelineParallelism.Options,
            (i, _) =>
            {
                processed[i] = DedupeText(ctx.History[i], ctx, ref collapsed, ref dropped, fileBlockCounts);
                return ValueTask.CompletedTask;
            });

        ctx.History = [.. processed];

        // Also dedupe the query itself
        ctx.Query = DedupeText(ctx.Query, ctx, ref collapsed, ref dropped, fileBlockCounts);

        // Spaghetti detection — check after all turns are processed
        foreach ((string? source, List<string>? hashes) in fileBlockCounts)
        {
            if (hashes.Count >= _config.SpaghettiBlockThreshold)
            {
                ctx.SpaghettiReport = new SpaghettiReport
                {
                    FilePath = source,
                    DuplicateBlockCount = hashes.Count,
                    BlockHashes = hashes.ToArray(),
                    Suggestion =
                        $"Consider extracting shared logic in {Path.GetFileName(source)} into a reusable method or class."
                };
                notes.Add($"Spaghetti detected: {hashes.Count} near-duplicate blocks in {source}");
                LogSpaghettiDetected(_logger, hashes.Count, source);
            }
        }

        if (collapsed > 0)
        {
            notes.Add($"{collapsed} duplicate blocks collapsed");
        }

        if (dropped > 0)
        {
            notes.Add($"{dropped} exact-duplicate blocks removed");
        }

        diag.OutputTokens = ctx.EstimateTokens();
        diag.ItemsCollapsed = collapsed;
        diag.ItemsDropped = dropped;
        diag.Elapsed = sw.Elapsed;
        diag.Notes = notes.ToArray();
        ctx.StageDiagnostics.Add(diag);

        LogStageSavings(_logger, Name, diag.TokensSaved, sw.ElapsedMilliseconds);
        return ctx;
    }

    private string DedupeText(
        string text,
        PipelineContext ctx,
        ref int collapsed,
        ref int dropped,
        Dictionary<string, List<string>> fileBlockCounts)
    {
        string result = text;
        int idx = 0;

        while (true)
        {
            int start = result.IndexOf("```", idx, StringComparison.Ordinal);
            if (start < 0)
            {
                break;
            }

            int end = result.IndexOf("```", start + 3, StringComparison.Ordinal);
            if (end < 0)
            {
                break;
            }

            string block = result[start..(end + 3)];
            string normalized = NormalizeBlock(block);
            string hash = HashString(normalized);

            if (!ctx.SeenBlockHashes.TryAdd(hash, 0))
            {
                // Exact duplicate
                int lines = block.Count(c => c == '\n');
                result = result[..start] + $"<code_block ref={hash[..8]} lines={lines}>" + result[(end + 3)..];
                _ = Interlocked.Increment(ref dropped);
                idx = start + 1;
            }
            else
            {
                // Check near-duplicates against already-seen blocks
                string? nearDupe = FindNearDuplicate(normalized, ctx);
                if (nearDupe != null)
                {
                    int lines = block.Count(c => c == '\n');
                    result = result[..start] + $"<near-duplicate ref={nearDupe[..8]} lines={lines}>" +
                             result[(end + 3)..];
                    _ = Interlocked.Increment(ref collapsed);
                    idx = start + 1;

                    // Track for spaghetti detection (guess source from surrounding text — best effort)
                    string sourceGuess = GuessSource(text, start);
                    lock (fileBlockCounts)
                    {
                        if (!fileBlockCounts.TryGetValue(sourceGuess, out List<string>? list))
                        {
                            fileBlockCounts[sourceGuess] = list = [];
                        }

                        list.Add(hash);

public partial class LogStrippingStage(IOptions<ContextHelperConfig> config, ILogger<LogStrippingStage> logger)
    : IPipelineStage
{
    [LoggerMessage(Level = LogLevel.Debug, Message = "{Stage}: {Lines} log lines stripped, saved {Saved} tokens")]
    private static partial void LogStripSummary(ILogger logger, string stage, int lines, int saved);

    private static readonly Regex LogLineRegex = new(
        @"^\s*(?:\[(?:INFO|DEBUG|TRACE|WARN|WARNING|ERROR|FATAL)\]|(?:INFO|DEBUG|TRACE|WARN|WARNING|ERROR|FATAL)\s*:|\d{4}-\d{2}-\d{2}[\sT]\d{2}:\d{2})",
        RegexOptions.Compiled | RegexOptions.IgnoreCase);

    private static readonly Regex FailureRegex = new(
        @"(?:ERROR|EXCEPTION|FAIL|FATAL)", RegexOptions.Compiled | RegexOptions.IgnoreCase);

    private readonly ContextHelperConfig _config = config.Value;

    public string Name => "LogStripping";

    public async Task<PipelineContext> ProcessAsync(PipelineContext ctx, CancellationToken ct = default)
    {
        Stopwatch sw = Stopwatch.StartNew();
        StageDiagnostic diag = new() { StageName = Name, InputTokens = ctx.EstimateTokens() };
        int linesStripped = 0;

        string[] processed = new string[ctx.History.Count];
        await Parallel.ForEachAsync(
            Enumerable.Range(0, ctx.History.Count),
            PipelineParallelism.Options,
            (i, _) =>
            {
                processed[i] = StripLogs(ctx.History[i], ref linesStripped);
                return ValueTask.CompletedTask;
            });

        ctx.History = [.. processed];
        ctx.Query = StripLogs(ctx.Query, ref linesStripped);

        diag.OutputTokens = ctx.EstimateTokens();
        diag.ItemsDropped = linesStripped;
        diag.Elapsed = sw.Elapsed;
        if (linesStripped > 0)
        {
            diag.Notes = [$"{linesStripped:N0} log lines stripped; failures + tail preserved"];
        }

        ctx.StageDiagnostics.Add(diag);

        LogStripSummary(logger, Name, linesStripped, diag.TokensSaved);
        return ctx;
    }

    private string StripLogs(string text, ref int stripped)
    {
        string[] lines = text.Split('\n');
        StringBuilder result = new();
        int i = 0;

        while (i < lines.Length)
        {
            // Detect start of a log block (3+ consecutive log lines)
            if (IsLogBlock(lines, i, out int blockEnd))
            {
                string[] block = lines[i..blockEnd];
                int totalCount = block.Length;
                string[] failures = block.Where(l => FailureRegex.IsMatch(l)).ToArray();
                string[] tail = block.TakeLast(Math.Min(_config.LogTailLines, totalCount)).ToArray();
                int omittedCount = totalCount - tail.Length;

                if (omittedCount > 0)
                {
                    _ = result.AppendLine(CultureInfo.InvariantCulture, $"<logs omitted: {omittedCount:N0} lines>");
                    _ = Interlocked.Add(ref stripped, omittedCount);
                }

                if (failures.Length > 0)
                {
                    _ = result.AppendLine("<failures>");
                    foreach (string? f in failures)
                    {
                        _ = result.AppendLine("  " + f.TrimStart());
                    }

                    _ = result.AppendLine("</failures>");
                }

                if (tail.Length > 0)
                {
                    _ = result.AppendLine(CultureInfo.InvariantCulture, $"<log tail: last {tail.Length} lines>");
                    foreach (string? t in tail)
                    {
                        _ = result.AppendLine(t);
                    }

                    _ = result.AppendLine("</log tail>");
                }

                i = blockEnd;
            }
            else
            {
                _ = result.AppendLine(lines[i]);
                i++;
            }
        }

        return result.ToString().TrimEnd();
    }

    private static bool IsLogBlock(string[] lines, int start, out int end)
    {
        end = start;
        int count = 0;
        for (int j = start; j < lines.Length; j++)
        {
            if (LogLineRegex.IsMatch(lines[j]))
            {
                count++;
                end = j + 1;
            }
            else if (count >= 3)
            {
                break;
            }
            else
            {
                end = start;
                return false;
            }
        }

        return count >= 3;
    }
}

public partial class CodeBlockCollapsingStage(IOptions<ContextHelperConfig> config, ILogger<CodeBlockCollapsingStage> logger)
    : IPipelineStage
{
    [LoggerMessage(Level = LogLevel.Debug, Message = "{Stage}: {N} blocks collapsed, saved {Saved} tokens")]
    private static partial void LogCollapseSummary(ILogger logger, string stage, int n, int saved);

    [GeneratedRegex(@"```(\w*)\n([\s\S]*?)```")]
    private static partial Regex FencedBlockRegex();

    private readonly ContextHelperConfig _config = config.Value;

    public string Name => "CodeBlockCollapsing";

    public async Task<PipelineContext> ProcessAsync(PipelineContext ctx, CancellationToken ct = default)
    {
        Stopwatch sw = Stopwatch.StartNew();
        StageDiagnostic diag = new() { StageName = Name, InputTokens = ctx.EstimateTokens() };

        // Weight adjustment: high code weight → raise threshold
        int threshold = _config.CodeBlockCollapseThreshold;
        if (ctx.Assessment.WeightProfile.CodeWeight >= 0.8)
        {
            threshold += 30;
        }

        int collapsed = 0;

        string[] processed = new string[ctx.History.Count];
        await Parallel.ForEachAsync(
            Enumerable.Range(0, ctx.History.Count),
            PipelineParallelism.Options,
            (i, innerCt) =>
            {
                (string? text, int count) = CollapseBlocks(ctx.History[i], ctx, threshold);
                processed[i] = text;
                _ = Interlocked.Add(ref collapsed, count);
                return ValueTask.CompletedTask;
            });

        ctx.History = [.. processed];
        (string? queryText, int queryCount) = CollapseBlocks(ctx.Query, ctx, threshold);
        ctx.Query = queryText;
        collapsed += queryCount;

        diag.OutputTokens = ctx.EstimateTokens();
        diag.ItemsCollapsed = collapsed;
        diag.Elapsed = sw.Elapsed;
        if (collapsed > 0)
        {
            diag.Notes = [$"{collapsed} code blocks collapsed (threshold={threshold} lines)"];
        }

        ctx.StageDiagnostics.Add(diag);

        LogCollapseSummary(logger, Name, collapsed, diag.TokensSaved);
        return ctx;
    }

    private static (string Text, int Count) CollapseBlocks(string text, PipelineContext ctx, int threshold)
    {
        int count = 0;
        string result = FencedBlockRegex().Replace(text, m =>
        {
            string lang = m.Groups[1].Value;
            string content = m.Groups[2].Value;
            int lines = content.Split('\n').Length;

            if (lines <= threshold)
            {
                return m.Value;
            }

            string hash = HashContent(content);
            string id = $"sha256:{hash}";

            _ = ctx.CollapsedBlocks.TryAdd(hash, m.Value);
            count++;

            return
                $"<code_block id={id} length={content.Length} lines={lines} lang={(string.IsNullOrEmpty(lang) ? "text" : lang)}>";
        });
        return (result, count);
    }

    private static string HashContent(string content)
    {
        byte[] bytes = SHA256.HashData(Encoding.UTF8.GetBytes(content));
        return Convert.ToHexString(bytes)[..16].ToUpperInvariant();
    }
}

public partial class ConversationSummarizationStage(
    HttpClient http,
    IOptions<ContextHelperConfig> config,
    ILogger<ConversationSummarizationStage> logger)
    : IPipelineStage
{
    [LoggerMessage(Level = LogLevel.Debug, Message = "{Stage}: summarized {N} turns, saved {Saved} tokens")]
    private static partial void LogSummarizationSummary(ILogger logger, string stage, int n, int saved);

    [LoggerMessage(Level = LogLevel.Warning, Message = "ConversationSummarization model call failed; keeping original text")]
    private static partial void LogSummarizationModelCallFailed(ILogger logger, Exception ex);

    // Garbage patterns to strip before summarizing to reduce token cost
    [GeneratedRegex(@"(?:Sure,?\s*|Of course[,!]?\s*|Certainly[,!]?\s*|Absolutely[,!]?\s*|Great[,!]?\s*)",
        RegexOptions.IgnoreCase)]
    private static partial Regex GreetingFillerPattern();

    [GeneratedRegex(@"Let me know if you need\s+\w+.*?\.", RegexOptions.IgnoreCase)]
    private static partial Regex LetMeKnowPattern();

    [GeneratedRegex(@"As an AI\b.*?\.", RegexOptions.IgnoreCase)]
    private static partial Regex AsAnAiPattern();

    [GeneratedRegex(@"I apologize\b.*?\.", RegexOptions.IgnoreCase)]
    private static partial Regex ApologyPattern();

    [GeneratedRegex(@"Hope that helps.*?\.", RegexOptions.IgnoreCase)]
    private static partial Regex HopeThatHelpsPattern();

    private static readonly Func<Regex>[] GarbagePatterns =
    [
        GreetingFillerPattern,
        LetMeKnowPattern,
        AsAnAiPattern,
        ApologyPattern,
        HopeThatHelpsPattern
    ];

    private readonly ContextHelperConfig _config = config.Value;

    public string Name => "ConversationSummarization";

    public async Task<PipelineContext> ProcessAsync(PipelineContext ctx, CancellationToken ct = default)
    {
        Stopwatch sw = Stopwatch.StartNew();
        StageDiagnostic diag = new() { StageName = Name, InputTokens = ctx.EstimateTokens() };

        // Weight adjustment: high conversation weight → keep more turns verbatim
        int verbatimTurns = _config.VerbatimTurns;
        if (ctx.Assessment.WeightProfile.ConversationWeight >= 0.8)
        {
            verbatimTurns += 2;
        }

        IReadOnlyList<string> history = ctx.History;
        if (history.Count <= verbatimTurns)
        {
            // Nothing to summarize
            diag.OutputTokens = ctx.EstimateTokens();
            diag.Elapsed = sw.Elapsed;
            ctx.StageDiagnostics.Add(diag);
            return ctx;
        }

        List<string> recent = [.. history.TakeLast(verbatimTurns)];
        List<string> older = [.. history.Take(history.Count - verbatimTurns)];

        // Strip garbage from older turns before summarizing to reduce model call cost
        string[] cleaned = older.Select(PreClean).ToArray();
        string combined = string.Join("\n\n", cleaned);

        string summary = await SummarizeAsync(combined, ctx.Assessment.Constraints, ctx.AvoidChainOfThought, ct);

        ctx.History = [$"<summary turns={older.Count}>\n{summary}\n</summary>", .. recent];

        diag.OutputTokens = ctx.EstimateTokens();
        diag.ItemsCollapsed = older.Count;
        diag.Elapsed = sw.Elapsed;
        diag.Notes = [$"{older.Count} older turns summarized, {verbatimTurns} kept verbatim"];
        ctx.StageDiagnostics.Add(diag);

        LogSummarizationSummary(logger, Name, older.Count, diag.TokensSaved);
        return ctx;
    }

    private static string PreClean(string text)
    {
        foreach (Func<Regex> p in GarbagePatterns)
        {
            text = p().Replace(text, "");
        }

        return text.Trim();
    }

    private async Task<string> SummarizeAsync(
        string text, IReadOnlyList<string> constraints, bool avoidChainOfThought, CancellationToken ct)
    {
        string constraintNote = constraints.Count > 0
            ? $"\nPreserve these constraints exactly: {string.Join("; ", constraints)}"
            : "";

        // Reasoning models (DeepSeek R1, Qwen3-thinking) do internal CoT deliberation.
        // A step-by-step prompt competes with their built-in reasoning and can cause
        // verbose or looping outputs.  Use a direct extraction prompt instead.
        string prompt = avoidChainOfThought
            ? $"""
               Extract a concise technical summary from the conversation below.
               Output only: file names, decisions, constraints, instructions, errors, code.
               No preamble, no explanation, no meta-commentary.{constraintNote}

               Conversation:
               {text}
               """
            : $"""
               Summarize the following conversation into a concise technical summary.
               Preserve: file names, decisions, stated constraints, explicit instructions, error messages, and code artifacts.
               Strip: pleasantries, hedging, meta-commentary about the AI.{constraintNote}

               Conversation:
               {text}
               """;

        try
        {
            var payload = new { model = "HelperModel", prompt, stream = false };
            HttpResponseMessage response = await http.PostAsJsonAsync("/api/generate", payload, ct);
            if (!response.IsSuccessStatusCode)
            {
                return text; // fallback: keep original
            }

            GenerateResponse? result = await response.Content.ReadFromJsonAsync<GenerateResponse>(ct);
            return result?.Response?.Trim() ?? text;
        }
        catch (Exception ex)
        {
            LogSummarizationModelCallFailed(logger, ex);
            return text;
        }
    }

public partial class ToolCallCompressionStage : IPipelineStage
{
