public class OllamaEndpointRegistryTests
{
    private static OllamaEndpointRegistry CreateRegistry(
        Collection<OllamaEndpointConfig> endpoints, EndpointSelectStrategy strategy = EndpointSelectStrategy.Failover)
    {
        TokenSaverConfig config = new()
        {
            Endpoints = endpoints,
            EndpointSelectStrategy = strategy
        };
        return new OllamaEndpointRegistry(
            Options.Create(config), NullLogger<OllamaEndpointRegistry>.Instance);
    }

    private static Collection<OllamaEndpointConfig> TwoEndpoints()
    {
        return
        [
            new OllamaEndpointConfig { Name = "primary", Url = "http://localhost:11435", Primary = true },
            new OllamaEndpointConfig { Name = "backup", Url = "http://localhost:11436", Primary = false }
        ];
    }

    [Fact]
    public void ZeroConfig_SynthesizesSingleDefaultEndpoint()
    {
        OllamaEndpointRegistry registry = CreateRegistry([]);

        IReadOnlyList<OllamaEndpointStatus> all = registry.GetAllEndpoints();

        _ = Assert.Single(all);
        Assert.Equal("default", all[0].Name);
        Assert.True(all[0].Primary);
        Assert.True(all[0].Healthy);
    }

    [Fact]
    public void Failover_UsesPrimaryWhenHealthy()
    {
        OllamaEndpointRegistry registry = CreateRegistry(TwoEndpoints());

        OllamaEndpointStatus selected = registry.SelectEndpoint();

        Assert.Equal("primary", selected.Name);
    }

    [Fact]
    public void Failover_SwitchesToBackupWhenPrimaryUnhealthy()
    {
        OllamaEndpointRegistry registry = CreateRegistry(TwoEndpoints());

        registry.RecordFailure("primary");

        OllamaEndpointStatus selected = registry.SelectEndpoint();

        Assert.Equal("backup", selected.Name);
    }

    [Fact]
    public void Failover_RecoversToPrimaryAfterSuccess()
    {
        OllamaEndpointRegistry registry = CreateRegistry(TwoEndpoints());

        registry.RecordFailure("primary");
        Assert.Equal("backup", registry.SelectEndpoint().Name);

        registry.RecordSuccess("primary");

        Assert.Equal("primary", registry.SelectEndpoint().Name);
    }

    [Fact]
    public void RoundRobin_DistributesAcrossHealthyEndpoints()
    {
        OllamaEndpointRegistry registry = CreateRegistry(TwoEndpoints(), EndpointSelectStrategy.RoundRobin);

        string first = registry.SelectEndpoint().Name;
        string second = registry.SelectEndpoint().Name;
        string third = registry.SelectEndpoint().Name;

        Assert.NotEqual(first, second);
        Assert.Equal(first, third); // cycles back after 2 healthy endpoints
    }

    [Fact]
    public void RoundRobin_SkipsUnhealthyEndpoint()
    {
        OllamaEndpointRegistry registry = CreateRegistry(TwoEndpoints(), EndpointSelectStrategy.RoundRobin);
        registry.RecordFailure("backup");

        OllamaEndpointStatus first = registry.SelectEndpoint();
        OllamaEndpointStatus second = registry.SelectEndpoint();

        Assert.Equal("primary", first.Name);
        Assert.Equal("primary", second.Name);
    }

    [Fact]
    public void Explicit_SelectsNamedEndpointWhenHealthy()
    {
        OllamaEndpointRegistry registry = CreateRegistry(TwoEndpoints());

        OllamaEndpointStatus selected = registry.SelectEndpoint("backup");

        Assert.Equal("backup", selected.Name);
    }

    [Fact]
    public void Explicit_FallsBackToPrimaryWhenNamedEndpointUnhealthy()
    {
        OllamaEndpointRegistry registry = CreateRegistry(TwoEndpoints());
        registry.RecordFailure("backup");

        OllamaEndpointStatus selected = registry.SelectEndpoint("backup");

        Assert.Equal("primary", selected.Name);
    }

    [Fact]
    public void Explicit_FallsBackToPrimaryWhenNamedEndpointUnknown()
    {
        OllamaEndpointRegistry registry = CreateRegistry(TwoEndpoints());

        OllamaEndpointStatus selected = registry.SelectEndpoint("does-not-exist");

        Assert.Equal("primary", selected.Name);
    }

    [Fact]
    public void RecordFailure_SetsNextRetryAtInTheFuture()
    {
        OllamaEndpointRegistry registry = CreateRegistry(TwoEndpoints());

        registry.RecordFailure("primary");

        OllamaEndpointStatus status = registry.GetAllEndpoints().Single(e => e.Name == "primary");
        _ = Assert.NotNull(status.NextRetryAt);
        Assert.True(status.NextRetryAt > DateTimeOffset.UtcNow);
        Assert.False(status.Healthy);
    }

public class SavingsTrackerTests : IDisposable
{
    private readonly string _tempWorkspace = Path.Combine(Path.GetTempPath(), "lh-savings-tests-" + Guid.NewGuid());

    public void Dispose()
    {
        if (Directory.Exists(_tempWorkspace))
        {
            try
            {
                Directory.Delete(_tempWorkspace, recursive: true);
            }
            catch (IOException)
            {
                // best-effort cleanup; SQLite file handles can linger briefly on Windows
            }
        }
    }

    private static SavingsTracker CreateTracker(TokenSaverConfig? config = null)
    {
        return new SavingsTracker(new TokenEconomyDbAccessor(), Options.Create(config ?? new TokenSaverConfig()));
    }

    [Fact]
    public void Verdict_NotEnoughCalls_ReturnsNullWorthIt()
    {
        TokenSaverConfig config = new();
        config.TokenEconomy.WorthItMinCalls = 5;
        SavingsTracker tracker = CreateTracker(config);

        SavingsAggregate aggregate = new("runTests", 2, 1000, 200, 800, 80, 500);

        SavingsVerdict verdict = tracker.Verdict(aggregate);

        Assert.Null(verdict.WorthIt);
        Assert.Contains("not enough calls", verdict.Reason, StringComparison.OrdinalIgnoreCase);
    }

    [Fact]
    public void Verdict_BelowMinPct_ReturnsFalse()
    {
        TokenSaverConfig config = new();
        config.TokenEconomy.WorthItMinCalls = 1;
        config.TokenEconomy.WorthItMinPct = 30;
        SavingsTracker tracker = CreateTracker(config);

        SavingsAggregate aggregate = new("runTests", 10, 1000, 900, 100, 10, 500); // 10% saved

        SavingsVerdict verdict = tracker.Verdict(aggregate);

        Assert.False(verdict.WorthIt);
        Assert.Contains("threshold", verdict.Reason, StringComparison.OrdinalIgnoreCase);
    }

    [Fact]
    public void Verdict_AboveMaxLatency_ReturnsFalseEvenWithGoodSavings()
    {
        TokenSaverConfig config = new();
        config.TokenEconomy.WorthItMinCalls = 1;
        config.TokenEconomy.WorthItMinPct = 30;
        config.TokenEconomy.WorthItMaxMs = 4000;
        SavingsTracker tracker = CreateTracker(config);

        SavingsAggregate aggregate = new("runTests", 10, 1000, 100, 900, 90, 9000); // 90% saved but slow

        SavingsVerdict verdict = tracker.Verdict(aggregate);

        Assert.False(verdict.WorthIt);
        Assert.Contains("exceeds", verdict.Reason, StringComparison.OrdinalIgnoreCase);
    }

    [Fact]
    public void Verdict_ClearsBothThresholds_ReturnsTrue()
    {
        TokenSaverConfig config = new();
        config.TokenEconomy.WorthItMinCalls = 1;
        config.TokenEconomy.WorthItMinPct = 30;
        config.TokenEconomy.WorthItMaxMs = 4000;
        SavingsTracker tracker = CreateTracker(config);

        SavingsAggregate aggregate = new("runTests", 10, 1000, 200, 800, 80, 1000);

        SavingsVerdict verdict = tracker.Verdict(aggregate);

        Assert.True(verdict.WorthIt);
    }

    [Fact]
    public async Task RecordAsync_TrackingDisabled_DoesNotPersistAnything()
    {
        TokenSaverConfig config = new();
        config.TokenEconomy.EnableSavingsTracking = false;
        SavingsTracker tracker = CreateTracker(config);

        await tracker.RecordAsync(_tempWorkspace, "runTests", "test_failure", false, 100, 20, 50);

        // With tracking disabled RecordAsync must return before ever opening the DB — if it had
        // opened one, GetReportAsync below (tracking re-enabled, fresh tracker) would still see
        // zero rows either way, so this test's real assertion is that no exception occurred and
        // no .tokensaver/index.db was created.
        Assert.False(File.Exists(WorkspaceIndexContextFactory.GetDbPath(_tempWorkspace)));
    }

    [Fact]
    public async Task RecordAsync_ThenGetReportAsync_AggregatesByTool()
    {
        SavingsTracker tracker = CreateTracker();

        await tracker.RecordAsync(_tempWorkspace, "runTests", "test_failure", false, 1000, 200, 500);
        await tracker.RecordAsync(_tempWorkspace, "runTests", "test_failure", false, 2000, 400, 700);
        await tracker.RecordAsync(_tempWorkspace, "containerLogs", "log_errors", true, 500, 100, 300);

        IReadOnlyList<SavingsAggregate> report = await tracker.GetReportAsync(_tempWorkspace, sinceDays: 7, groupByRole: false);

        Assert.Equal(2, report.Count);
        SavingsAggregate runTests = Assert.Single(report, r => r.Name == "runTests");
        Assert.Equal(2, runTests.Calls);
        Assert.Equal(3000, runTests.RawTokens);
        Assert.Equal(600, runTests.DistilledTokens);
        Assert.Equal(2400, runTests.SavedTokens);
        // Ranked by saved_tokens descending — runTests (2400 saved) should outrank containerLogs (400 saved).
        Assert.Equal("runTests", report[0].Name);
    }

    [Fact]
    public async Task GetOneAsync_NoMatchingRows_ReturnsEmptyWithZeroCalls()
    {
        SavingsTracker tracker = CreateTracker();

        SavingsAggregate result = await tracker.GetOneAsync(_tempWorkspace, "nonexistentTool", groupByRole: false, sinceDays: 30);

        Assert.Equal(0, result.Calls);
    }
}

public sealed class TokenEconomyDbAccessor : IDisposable
{
    private readonly SemaphoreSlim _dbLock = new(1, 1);
    private readonly SemaphoreSlim _ctxOpenLock = new(1, 1);
    private WorkspaceIndexContext? _ctx;
    private string? _ctxWorkspaceRoot;

    public void Dispose()
    {
        _ctx?.Dispose();
        _ctxOpenLock.Dispose();
        _dbLock.Dispose();
    }

    public async Task<WorkspaceIndexContext> GetDbAsync(string workspaceRoot, CancellationToken ct)
    {
        if (_ctx != null && _ctxWorkspaceRoot == workspaceRoot)
        {
            return _ctx;
        }

        await _ctxOpenLock.WaitAsync(ct);
        try
        {
            if (_ctx != null && _ctxWorkspaceRoot == workspaceRoot)
            {
                return _ctx;
            }

            if (_ctx is not null)
            {
                await _ctx.DisposeAsync();
            }

            _ctx = await WorkspaceIndexContextFactory.CreateAsync(workspaceRoot, ct);
            _ctxWorkspaceRoot = workspaceRoot;
            return _ctx;
        }
        finally
        {
            _ = _ctxOpenLock.Release();
        }
    }

    /// <summary>Runs <paramref name="action" /> while holding the DB lock, returning its result.</summary>
    public async Task<T> WithDbLockAsync<T>(Func<Task<T>> action, CancellationToken ct)
    {
        await _dbLock.WaitAsync(ct);
        try
        {
            return await action();
        }
        finally
        {
            _ = _dbLock.Release();
        }
    }

    /// <summary>Void-returning overload of <see cref="WithDbLockAsync{T}(Func{Task{T}},CancellationToken)" />.</summary>
    public async Task WithDbLockAsync(Func<Task> action, CancellationToken ct)
    {
        await _dbLock.WaitAsync(ct);
        try
        {
            await action();
        }
        finally
        {
            _ = _dbLock.Release();
        }
    }
}

public async Task<T> WithDbLockAsync<T>(Func<Task<T>> action, CancellationToken ct)
{
    await _dbLock.WaitAsync(ct);
    try
    {
        return await action();
    }
    finally
    {
        _ = _dbLock.Release();
    }
}

public async Task WithDbLockAsync(Func<Task> action, CancellationToken ct)
{
    await _dbLock.WaitAsync(ct);
    try
    {
        await action();
    }
    finally
    {
        _ = _dbLock.Release();
    }
}

public class WorkspaceIndexContext(DbContextOptions<WorkspaceIndexContext> options) : DbContext(options)
{
    public DbSet<FolderEntity> Folders => Set<FolderEntity>();
    public DbSet<FileEntity> Files => Set<FileEntity>();
    public DbSet<SymbolEntity> Symbols => Set<SymbolEntity>();
    public DbSet<SymbolReferenceEntity> SymbolReferences => Set<SymbolReferenceEntity>();
    public DbSet<RepoStalenessEntity> RepoStaleness => Set<RepoStalenessEntity>();

    /// <summary>Function/class/markdown-section chunks — see ChunkEntity. Populated by RepoIndexer, queried by SemanticGrep.</summary>
    public DbSet<ChunkEntity> Chunks => Set<ChunkEntity>();

    /// <summary>Per-distill()-call savings log — see TokenSavingsEntity. Populated by SavingsTracker, queried by TokenSavingsReport/WorthKeeping.</summary>
    public DbSet<TokenSavingsEntity> TokenSavings => Set<TokenSavingsEntity>();

    /// <summary>
    ///     Keyless entity backed by the folder_overview view. Read-only — see
    ///     <see cref="WorkspaceIndexContextFactory.CreateAsync" /> for where the view is created.
    /// </summary>
    public DbSet<FolderOverview> FolderOverviews => Set<FolderOverview>();

    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        _ = modelBuilder.Entity<FolderEntity>(e =>
        {
            _ = e.HasIndex(f => f.RelativePath).IsUnique();
            _ = e.HasOne(f => f.ParentFolder)
                .WithMany(f => f.ChildFolders)
                .HasForeignKey(f => f.ParentFolderId)
                .OnDelete(DeleteBehavior.Restrict); // self-referencing — avoid cascade cycles
        });

        _ = modelBuilder.Entity<FileEntity>(e =>
        {
            _ = e.HasIndex(f => f.RelativePath).IsUnique();
            _ = e.HasOne(f => f.Folder)
                .WithMany(f => f.Files)
                .HasForeignKey(f => f.FolderId)
                .OnDelete(DeleteBehavior.Cascade);
        });

        _ = modelBuilder.Entity<SymbolEntity>(e =>
        {
            _ = e.HasIndex(s => s.Name);
            _ = e.HasIndex(s => s.FileId);
            _ = e.HasOne(s => s.File)
                .WithMany(f => f.Symbols)
                .HasForeignKey(s => s.FileId)
                .OnDelete(DeleteBehavior.Cascade);
        });

        _ = modelBuilder.Entity<SymbolReferenceEntity>(e =>
        {
            _ = e.HasIndex(r => r.SourceSymbolId);
            _ = e.HasIndex(r => r.TargetSymbolId);
        });

        _ = modelBuilder.Entity<RepoStalenessEntity>(e => { _ = e.HasKey(r => r.RepoRootPath); });

        _ = modelBuilder.Entity<ChunkEntity>(e =>
        {
            _ = e.HasIndex(c => c.RelativePath);
            _ = e.HasIndex(c => new { c.RelativePath, c.StartLine, c.EndLine }).IsUnique();
        });

        _ = modelBuilder.Entity<TokenSavingsEntity>(e =>
        {
            _ = e.HasIndex(t => t.Tool);
            _ = e.HasIndex(t => t.Role);
            _ = e.HasIndex(t => t.CreatedAt);
        });

        _ = modelBuilder.Entity<FolderOverview>(e =>
        {
            _ = e.HasNoKey();
            _ = e.ToView("folder_overview");
        });
    }
}

public static class WorkspaceIndexContextFactory
{
    public const string TokenSaverFolderName = ".tokensaver";
    public const string IndexFileName = "index.db";

    public static string GetDbPath(string workspaceRoot)
    {
        return Path.Combine(workspaceRoot, TokenSaverFolderName, IndexFileName);
    }

    /// <summary>
    ///     Opens (creating if needed) the unified workspace index for the given workspace root,
    ///     ensures the schema exists, enables WAL, and (re)creates the folder_overview view.
    /// </summary>
    public static async Task<WorkspaceIndexContext> CreateAsync(string workspaceRoot, CancellationToken ct = default)
    {
        string dbPath = GetDbPath(workspaceRoot);
        _ = Directory.CreateDirectory(Path.GetDirectoryName(dbPath)!);

        DbContextOptions<WorkspaceIndexContext> options = new DbContextOptionsBuilder<WorkspaceIndexContext>()
            .UseSqlite($"Data Source={dbPath}")
            .Options;

        WorkspaceIndexContext ctx = new(options);
        _ = await ctx.Database.EnsureCreatedAsync(ct);

        // WAL: lets MCP tool reads proceed while a background indexing write is in flight.
        _ = await ctx.Database.ExecuteSqlRawAsync("PRAGMA journal_mode=WAL;", ct);

        // EnsureCreatedAsync only emits DDL when the database file doesn't exist yet — a workspace
        // whose index.db predates the Chunks/TokenSavings tables (added for the token-economy tool
        // surface) will NOT get them from EnsureCreatedAsync alone. Create both defensively with
        // IF NOT EXISTS, matching the DDL EF's Sqlite provider would generate from the ChunkEntity/
        // TokenSavingsEntity configuration in WorkspaceIndexContext.OnModelCreating — harmless no-op
        // on a freshly-created database where EnsureCreatedAsync already made them.
        _ = await ctx.Database.ExecuteSqlRawAsync(
            """
            CREATE TABLE IF NOT EXISTS "Chunks" (
                "Id" INTEGER NOT NULL CONSTRAINT "PK_Chunks" PRIMARY KEY AUTOINCREMENT,
                "RelativePath" TEXT NOT NULL,
                "ChunkType" TEXT NOT NULL,
                "Name" TEXT NOT NULL,
                "StartLine" INTEGER NOT NULL,
                "EndLine" INTEGER NOT NULL,
                "ContentHash" TEXT NOT NULL,
                "Summary" TEXT NOT NULL,
                "EmbeddingVector" TEXT NOT NULL,
                "UpdatedAt" INTEGER NOT NULL
            );
            """, ct);
        _ = await ctx.Database.ExecuteSqlRawAsync(
            """CREATE INDEX IF NOT EXISTS "IX_Chunks_RelativePath" ON "Chunks" ("RelativePath");""", ct);
        _ = await ctx.Database.ExecuteSqlRawAsync(
            """CREATE UNIQUE INDEX IF NOT EXISTS "IX_Chunks_RelativePath_StartLine_EndLine" ON "Chunks" ("RelativePath", "StartLine", "EndLine");""",
            ct);

        _ = await ctx.Database.ExecuteSqlRawAsync(
            """
            CREATE TABLE IF NOT EXISTS "TokenSavings" (
                "Id" INTEGER NOT NULL CONSTRAINT "PK_TokenSavings" PRIMARY KEY AUTOINCREMENT,
                "Tool" TEXT NOT NULL,
                "Role" TEXT NOT NULL,
                "Terse" INTEGER NOT NULL,
                "RawTokens" INTEGER NOT NULL,
                "DistilledTokens" INTEGER NOT NULL,
                "SavedTokens" INTEGER NOT NULL,
                "DurationMs" INTEGER NOT NULL,
                "CreatedAt" INTEGER NOT NULL
            );
            """, ct);
        _ = await ctx.Database.ExecuteSqlRawAsync(
            """CREATE INDEX IF NOT EXISTS "IX_TokenSavings_Tool" ON "TokenSavings" ("Tool");""", ct);
        _ = await ctx.Database.ExecuteSqlRawAsync(
            """CREATE INDEX IF NOT EXISTS "IX_TokenSavings_Role" ON "TokenSavings" ("Role");""", ct);
        _ = await ctx.Database.ExecuteSqlRawAsync(
            """CREATE INDEX IF NOT EXISTS "IX_TokenSavings_CreatedAt" ON "TokenSavings" ("CreatedAt");""", ct);

        // EnsureCreated does not emit DDL for entities mapped ToView — create it ourselves.
        // Table names below match EF's default naming (DbSet property names): Folders, Files, Symbols.
        _ = await ctx.Database.ExecuteSqlRawAsync(
            """
            CREATE VIEW IF NOT EXISTS folder_overview AS
            SELECT
              f."Id"            AS "Id",
              f."RelativePath"  AS "RelativePath",
              f."Description"   AS "Description",
              f."LastModified"  AS "LastModified",
              COUNT(DISTINCT fi."Id")  AS "FileCount",
              COUNT(DISTINCT sy."Id")  AS "SymbolCount",
              MAX(fi."LastModified")   AS "MaxChildLastModified"
            FROM "Folders" f
            LEFT JOIN "Files" fi   ON fi."FolderId" = f."Id"
            LEFT JOIN "Symbols" sy ON sy."FileId"   = fi."Id"
            GROUP BY f."Id";
            """, ct);

        return ctx;
    }
}

public static async Task<WorkspaceIndexContext> CreateAsync(string workspaceRoot, CancellationToken ct = default)
{
