internal static void MigrateLegacyDataFolder(string workspaceRoot, ILogger logger)
{
    string current = Path.Combine(workspaceRoot, ".tokensaver");
    string legacy = Path.Combine(workspaceRoot, ".local-helper");

    if (Directory.Exists(current) || !Directory.Exists(legacy))
    {
        return;
    }

    try
    {
        Directory.Move(legacy, current);
        Program.LogLegacyDataFolderMigrated(logger, legacy, current);
    }
    catch (Exception ex) when (ex is IOException or UnauthorizedAccessException)
    {
        // Best effort — e.g. a file inside is open/locked by another process. Leave the
        // legacy folder in place; callers that resolve paths under ".tokensaver" simply
        // won't find existing data until a subsequent successful migration attempt.
        Program.LogLegacyDataFolderMigrationFailed(logger, ex, legacy, current);
    }
}

internal sealed class DraftModelHealthCheck(OllamaService ollama) : IHealthCheck
{
    public async Task<HealthCheckResult> CheckHealthAsync(
        HealthCheckContext context,
        CancellationToken cancellationToken = default)
    {
        OllamaStatusResult status;
        try
        {
            status = await ollama.GetOllamaStatusAsync();
        }
        catch (Exception ex)
        {
            return HealthCheckResult.Unhealthy(
                "DraftModel router threw an exception during health probe.",
                ex);
        }

        if (!status.Running)
        {
            return HealthCheckResult.Unhealthy(
                "DraftModel router is not reachable. " +
                "Ensure DraftModel.Loader is running (dotnet run --project DraftModel/DraftModel.Loader -- --service).");
        }

        if (status.Models.Length == 0)
        {
            return HealthCheckResult.Unhealthy(
                "DraftModel router is reachable but no models are pulled. " +
                "Run DraftModel.Loader with --service to pull required models.");
        }

        bool idle = status.LoadedInVram.Length == 0;
        Dictionary<string, object> data = new()
        {
            ["models_available"] = status.Models,
            ["models_in_vram"] = status.LoadedInVram,
            ["vram_state"] = idle ? "idle" : "loaded"
        };

        return idle
            ? HealthCheckResult.Healthy(
                $"DraftModel router is up with {status.Models.Length} model(s) available, " +
                "but idle — none currently loaded in VRAM (keep_alive expired). " +
                "Next request will incur a one-time cold-load delay.",
                data)
            : HealthCheckResult.Healthy(
                $"DraftModel router is healthy. " +
                $"{status.LoadedInVram.Length}/{status.Models.Length} model(s) loaded in VRAM.",
                data);
    }
}

internal sealed class SelfTestHealthCheck(
    IOptions<TokenSaverConfig> config,
    OllamaEndpointRegistry endpointRegistry) : IHealthCheck
{
    /// <summary>
    ///     Extra checks appended to the built-in suite. Empty in production; tests use this to
    ///     inject a deliberately-failing check without needing to break real config/wiring, to
    ///     verify the degraded-status wiring end to end.
    /// </summary>
    internal List<(string Name, Func<bool> Check)> ExtraChecks { get; } = [];

    public Task<HealthCheckResult> CheckHealthAsync(
        HealthCheckContext context,
        CancellationToken cancellationToken = default)
    {
        List<(string Name, Func<bool> Check)> checks =
        [
            ("config-bound", () => !string.IsNullOrWhiteSpace(config.Value.OllamaUrl)),
            ("workspace-root-resolvable", () =>
                string.IsNullOrWhiteSpace(config.Value.WorkspaceRoot) ||
                Directory.Exists(config.Value.WorkspaceRoot)),
            ("endpoint-registry-has-endpoint", () => endpointRegistry.GetAllEndpoints().Count > 0),
            .. ExtraChecks
        ];

        List<object> results = new(checks.Count);
        bool allOk = true;
        foreach ((string name, Func<bool> check) in checks)
        {
            try
            {
                bool ok = check();
                results.Add(new { name, ok, error = ok ? null : "check returned false" });
                allOk &= ok;
            }
            catch (Exception ex)
            {
                results.Add(new { name, ok = false, error = ex.Message });
                allOk = false;
            }
        }

        Dictionary<string, object> data = new() { ["checks"] = results };

        HealthCheckResult result = allOk
            ? HealthCheckResult.Healthy("Self-test checks passed.", data)
            : HealthCheckResult.Degraded("One or more self-test checks failed.", data: data);

        return Task.FromResult(result);
    }
}

internal sealed class UnhandledFaultHealthCheck(UnhandledFaultTracker faultTracker) : IHealthCheck
{
    public Task<HealthCheckResult> CheckHealthAsync(
        HealthCheckContext context,
        CancellationToken cancellationToken = default)
    {
        string? faultMessage = faultTracker.LastFaultMessage;

        HealthCheckResult result = faultMessage is null
            ? HealthCheckResult.Healthy("No unhandled exceptions recorded recently.")
            : HealthCheckResult.Degraded(
                $"An unhandled exception occurred recently: {faultMessage}",
                data: new Dictionary<string, object> { ["lastError"] = faultMessage });

        return Task.FromResult(result);
    }
}

internal sealed partial class ContextInterceptMiddleware
{
    [LoggerMessage(Level = LogLevel.Debug, Message = "Context cleaned for tool {Tool}: {Before} → {After} chars")]
    private static partial void LogContextCleaned(ILogger logger, string tool, int before, int after);

    [LoggerMessage(Level = LogLevel.Information, Message = "Draft model handled request for tool {Tool}: {Summary}")]
    private static partial void LogDraftModelHandled(ILogger logger, string tool, string? summary);

    [LoggerMessage(Level = LogLevel.Warning, Message = "Context cleaning pipeline failed for tool {Tool} — passing through")]
    private static partial void LogContextCleaningFailed(ILogger logger, Exception ex, string tool);

    [LoggerMessage(Level = LogLevel.Information, Message = "Draft model deferred for tool {Tool}. Prompt augmented with guidance request.")]
    private static partial void LogDraftModelDeferred(ILogger logger, string tool);

    [LoggerMessage(Level = LogLevel.Warning, Message = "Draft model interceptor failed for tool {Tool} — passing through")]
    private static partial void LogDraftModelInterceptorFailed(ILogger logger, Exception ex, string tool);

    private static readonly HashSet<string> _skipTools = new(StringComparer.OrdinalIgnoreCase)
    {
        "clean_and_chat",
        "build_concise_context",
        "context_hygiene",
        "context_diag",
        "help",
        "code_work"
    };

    // This middleware buffers the full request body into memory (EnableBuffering +
    // ReadToEndAsync) to peek at the JSON-RPC method/tool name before deciding whether to
    // intercept. Even though this server only listens on localhost/trusted MCP clients, a
    // single malformed or unexpectedly large payload (e.g. a huge pasted context/history
    // array) could otherwise force an unbounded in-memory allocation here. 25 MB comfortably
    // covers realistic prompt/context payloads while capping worst-case memory use.
    private const long MaxInterceptedBodyBytes = 25 * 1024 * 1024;

    private readonly ILogger<ContextInterceptMiddleware> _logger;

    private readonly RequestDelegate _next;

    public ContextInterceptMiddleware(
        RequestDelegate next,
        ILogger<ContextInterceptMiddleware> logger)
    {
        _next = next;
        _logger = logger;
    }

    public async Task InvokeAsync(
        HttpContext context,
        IOptions<CodeHelperConfig> codeHelperOpts,
        ContextCleanerService cleaner,
        DraftModelInterceptorService draftModelInterceptor)
    {
        if (!codeHelperOpts.Value.AutoEnabled ||
            context.Request.Method != HttpMethods.Post ||
            !context.Request.Path.StartsWithSegments("/mcp", StringComparison.OrdinalIgnoreCase))
        {
            await _next(context);
            return;
        }

        // Skip interception (rather than buffering) for bodies that are too large to be a
        // reasonable tool-call payload. An unknown/unset Content-Length is let through here —
        // the chunked read loop below still enforces the same cap as data streams in, so a
        // client that lies about or omits Content-Length can't bypass the limit.
        if (context.Request.ContentLength is > MaxInterceptedBodyBytes)
        {
            await _next(context);
            return;
        }

        // Buffer the request body so we can read and potentially replace it
        context.Request.EnableBuffering(bufferThreshold: (int)MaxInterceptedBodyBytes);
        using StreamReader reader = new(context.Request.Body, Encoding.UTF8, leaveOpen: true);
        char[] buffer = new char[81_920];
        StringBuilder bodyBuilder = new();
        int charsRead;
        while ((charsRead = await reader.ReadAsync(buffer)) > 0)
        {
            _ = bodyBuilder.Append(buffer, 0, charsRead);
            if (bodyBuilder.Length > MaxInterceptedBodyBytes)
            {
                // Body exceeded the cap mid-stream (Content-Length was absent/understated).
                // Bail out of interception entirely rather than truncating and risking a
                // subtly-corrupted JSON-RPC payload being parsed downstream.
                context.Request.Body.Position = 0;
                await _next(context);
                return;
            }
        }

        string body = bodyBuilder.ToString();
        context.Request.Body.Position = 0;

        JsonNode? rpc;
        try
        {
            rpc = JsonNode.Parse(body);
        }
        catch
        {
            await _next(context);
            return;
        }

        // Only intercept tools/call
        if (rpc?["method"]?.GetValue<string>() != "tools/call")
        {
            await _next(context);
            return;
        }

        string? toolName = rpc["params"]?["name"]?.GetValue<string>();
        if (toolName == null || _skipTools.Contains(toolName))
        {
            await _next(context);
            return;
        }

        JsonObject? args = rpc["params"]?["arguments"] as JsonObject;
        string? prompt = args?["prompt"]?.GetValue<string>();
        if (string.IsNullOrWhiteSpace(prompt))
        {
            await _next(context);
            return;
        }

        // Step 1: Run context cleaning pipeline
        string cleanedPrompt;
        try
        {
            // Extract optional history array
            string[]? history = null;
            if (args?["history"] is JsonArray historyNode)
            {
                history = historyNode
                    .Select(n => n?.GetValue<string>())
                    .Where(s => s != null)
                    .ToArray()!;
            }

internal sealed class FaultTrackingMiddleware(RequestDelegate next, UnhandledFaultTracker faultTracker)
{
    public async Task InvokeAsync(HttpContext context)
    {
        try
        {
            await next(context);
        }
        catch (Exception ex)
        {
            faultTracker.RecordFault(ex);
            throw;
        }
    }
}

internal sealed class AgentHelpersPromptAdapter(
    AgentAdapterRegistry registry,
    IOptions<TokenSaverConfig> config) : IPromptAdapter
{
