        DistillResult result = await distill.DistillAsync(_config.WorkspaceRoot, "diffSummarize", DistillRole.DiffSummary, diff, ct: ct);
        return $"{result.Summary}\n\n[{result.RawTokens}→{result.DistilledTokens} tokens]";
