{
    private readonly TokenSaverConfig _config = config.Value;

    [McpServerTool]
    [Description(
        "Chunk the workspace into function/class/markdown-section pieces and summarize+embed each new or " +
        "changed one via the local model (incremental — unchanged chunks are skipped by content hash). Run this " +
        "before SemanticGrep the first time, and again after significant edits.")]
    public async Task<string> IndexRepo(
        [Description("Workspace root to index; defaults to the configured WorkspaceRoot")]
        string? rootPath = null,
        [Description("File extensions to include, e.g. ['.cs','.md']; defaults to .cs/.js/.ts/.py/.md")]
        string[]? extensions = null,
        [Description("Max concurrent Ollama calls while indexing")]
        int concurrency = 4,
        CancellationToken ct = default)
    {
        string root = string.IsNullOrWhiteSpace(rootPath) ? _config.WorkspaceRoot : rootPath;
        RepoIndexStats stats = await indexer.IndexRepoAsync(root, extensions, concurrency, ct);
        return JsonSerializer.Serialize(new
        {
            files = stats.FilesScanned,
            chunks_indexed = stats.ChunksIndexed,
            chunks_skipped = stats.ChunksSkipped,
            chunks_deleted = stats.ChunksDeleted,
            elapsed_seconds = Math.Round(stats.Elapsed.TotalSeconds, 1)
        });
    }

    [McpServerTool]
    [Description(
        "Natural-language search over the chunk index built by IndexRepo. Returns file/lines/summary/score per " +
        "hit — not raw code; read the actual file only for the 1-2 hits that look relevant. Returns an empty " +
        "result set (not an error) if IndexRepo hasn't been run yet.")]
    public async Task<string> SemanticGrep(
        [Description("Natural-language query")] string query,
        [Description("Optional substring filter on the relative file path")]
        string? pathFilter = null,
        [Description("Number of top results to return (default 5)")]
        int topK = 5,
        CancellationToken ct = default)
    {
        IReadOnlyList<SemanticSearchHit> hits = await search.SearchAsync(_config.WorkspaceRoot, query, pathFilter, topK, ct);
        return JsonSerializer.Serialize(hits.Select(h => new
        {
            file = h.RelativePath,
            lines = $"{h.StartLine}-{h.EndLine}",
            type = h.ChunkType,
            name = h.Name,
            summary = h.Summary,
            score = h.Score
        }));
    }
}

internal sealed class SessionTools(IDistillationService distill, IOptions<TokenSaverConfig> config)
{
    private const int DistillThresholdChars = 4000;
    private readonly TokenSaverConfig _config = config.Value;

    [McpServerTool]
    [Description(
        "Save a session context blob to disk for later restore. Blobs over ~4000 characters are distilled " +
        "to a quick-restore summary automatically; the full original is kept alongside on disk regardless.")]
    public async Task<string> SessionSnapshot(
        [Description("Identifier for this session — used as the snapshot filename")]
        string sessionId,
        [Description("The context blob to save")] string contextBlob,
        [Description("Optional explicit output path; defaults to <WorkspaceRoot>/.tokensaver/sessions/<sessionId>.json")]
        string? outputPath = null,
        CancellationToken ct = default)
    {
        string root = string.IsNullOrWhiteSpace(_config.WorkspaceRoot) ? Directory.GetCurrentDirectory() : _config.WorkspaceRoot;
        string dest = outputPath ?? Path.Combine(root, ".tokensaver", "sessions", $"{sessionId}.json");
        _ = Directory.CreateDirectory(Path.GetDirectoryName(dest)!);

        string summary;
        if (contextBlob.Length > DistillThresholdChars)
        {
            DistillResult result = await distill.DistillAsync(
                _config.WorkspaceRoot, "sessionSnapshot", DistillRole.GenericCondense, contextBlob, maxTokens: 400, ct: ct);
            summary = result.Summary;
        }
        else
        {
            summary = contextBlob;
        }

        string fullBlobPath = dest.Replace(".json", ".full.txt", StringComparison.Ordinal);
        await File.WriteAllTextAsync(dest, JsonSerializer.Serialize(new
        {
            session_id = sessionId,
            saved_at = DateTimeOffset.UtcNow.ToString("O"),
            summary,
            full_blob_path = fullBlobPath
        }), ct);
        await File.WriteAllTextAsync(fullBlobPath, contextBlob, ct);

        return $"Saved snapshot: {dest}";
    }

    [McpServerTool]
    [Description(
        "Restore a previously saved session snapshot. Returns the distilled summary by default; pass full:true " +
        "to read back the original untruncated blob instead.")]
    public async Task<string> SessionRestore(
        [Description("Path to the .json snapshot file written by SessionSnapshot")]
        string snapshotPath,
        [Description("Return the full original blob instead of the distilled summary")]
        bool full = false,
        CancellationToken ct = default)
    {
        string json = await File.ReadAllTextAsync(snapshotPath, ct);
        using JsonDocument doc = JsonDocument.Parse(json);

        if (!full)
        {
            return doc.RootElement.GetProperty("summary").GetString() ?? "";
        }

        string fullBlobPath = doc.RootElement.GetProperty("full_blob_path").GetString()
            ?? throw new InvalidOperationException($"Snapshot at '{snapshotPath}' has no full_blob_path.");
        return await File.ReadAllTextAsync(fullBlobPath, ct);
    }
}

internal sealed class TokenEconomyTools(
    IDistillationService distill,
    ISavingsTracker savings,
    ModelRouteResolver modelRoutes,
    OllamaService ollama,
    IOptions<TokenSaverConfig> config)
{
    private readonly TokenSaverConfig _config = config.Value;

    // ── TokenBudget ──────────────────────────────────────────────────────────

    [McpServerTool]
    [Description(
        "Estimate the token cost of a piece of content and whether it exceeds a budget threshold. " +
        "Pure calculation, no model call — use before deciding whether to distill/truncate something yourself.")]
    public string TokenBudget(
        [Description("Text to measure")] string content,
        [Description("Token threshold to compare against (default 8000)")]
        int threshold = 8000)
    {
        int tokens = distill.EstimateTokens(content);
        var result = new
        {
            tokens,
            threshold,
            over_budget = tokens > threshold,
            pct_of_threshold = threshold > 0 ? (int)Math.Round(100.0 * tokens / threshold) : 0
        };
        return JsonSerializer.Serialize(result);
    }

    // ── ModelRoute ───────────────────────────────────────────────────────────

    [McpServerTool]
    [Description(
        "Call a local Ollama model chosen by task_type (code | chat | summarize | embed | rerank) rather than " +
        "naming a model directly — centralizes model choice per TokenEconomyConfig.ModelRoutes. " +
        "For embeddings use task_type='embed' and expect a JSON float array response, not a chat completion.")]
    public async Task<string> ModelRoute(
        [Description("Routing key: 'code', 'chat', 'summarize', 'embed', or 'rerank'")]
        string taskType,
        [Description("Prompt (or text to embed, when task_type='embed')")]
        string prompt,
        [Description("Max output tokens for non-embed task types")]
        int maxTokens = 400,
        CancellationToken ct = default)
    {
        string model = modelRoutes.Resolve(taskType);
        if (string.Equals(taskType, "embed", StringComparison.OrdinalIgnoreCase))
        {
            float[] vector = await ollama.EmbedAsync(model, prompt, ct: ct);
            return JsonSerializer.Serialize(vector);
        }

        return await ollama.CallModelAsync(model, prompt, ct);
    }

    // ── TokenSavingsReport ───────────────────────────────────────────────────

    [McpServerTool]
    [Description(
        "Ranked rollup of recorded token savings, grouped by tool or role, over the last N days. " +
        "Sorted by saved_tokens descending, each row includes a worth_it verdict — the top row answers " +
        "\"what's saving the most tokens\" without manual aggregation.")]
    public async Task<string> TokenSavingsReport(
        [Description("Lookback window in days (default 7)")] int sinceDays = 7,
        [Description("'tool' (default) or 'role'")] string groupBy = "tool",
        CancellationToken ct = default)
    {
        bool byRole = string.Equals(groupBy, "role", StringComparison.OrdinalIgnoreCase);
        IReadOnlyList<SavingsAggregate> rows = await savings.GetReportAsync(_config.WorkspaceRoot, sinceDays, byRole, ct);

        var results = rows.Select(r =>
        {
            SavingsVerdict v = savings.Verdict(r);
            return new
            {
                name = r.Name,
                calls = r.Calls,
                raw_tokens = r.RawTokens,
                distilled_tokens = r.DistilledTokens,
                saved_tokens = r.SavedTokens,
                pct_saved = r.PctSaved,
                avg_duration_ms = r.AvgDurationMs,
                worth_it = v.WorthIt,
                reason = v.Reason
            };
        });

        return JsonSerializer.Serialize(new { since_days = sinceDays, ranked_by = "saved_tokens", results });
    }

    // ── WorthKeeping ─────────────────────────────────────────────────────────

    [McpServerTool]
    [Description(
        "Direct yes/no/unknown verdict for one tool or role's distillation: is it saving enough tokens per " +
        "millisecond spent to be worth keeping on? Use TokenSavingsReport for the full ranked picture instead " +
        "if you want more than one target.")]
    public async Task<string> WorthKeeping(
        [Description("Tool or role name to judge, e.g. 'runTests' or 'test_failure'")]
        string target,
        [Description("'tool' (default) or 'role' — which column target matches")]
        string groupBy = "tool",
        [Description("Lookback window in days (default 30)")]
        int sinceDays = 30,
        CancellationToken ct = default)
    {
        bool byRole = string.Equals(groupBy, "role", StringComparison.OrdinalIgnoreCase);
        SavingsAggregate row = await savings.GetOneAsync(_config.WorkspaceRoot, target, byRole, sinceDays, ct);

        if (row.Calls == 0)
        {
            return JsonSerializer.Serialize(new { target, worth_it = (bool?)null, reason = "no data for this target" });
        }

        SavingsVerdict v = savings.Verdict(row);
        return JsonSerializer.Serialize(new
        {
            target,
            calls = row.Calls,
            raw_tokens = row.RawTokens,
            distilled_tokens = row.DistilledTokens,
            saved_tokens = row.SavedTokens,
            pct_saved = row.PctSaved,
            avg_duration_ms = row.AvgDurationMs,
            worth_it = v.WorthIt,
            reason = v.Reason
        });
    }
}

public sealed class DegradedHealthTests
{
    [Fact]
    public async Task Baseline_Health_IsHealthy()
    {
        await using HealthTestHost host = HealthTestHost.Create();

        using HttpResponseMessage response = await host.Client.GetAsync("/health");
        JsonDocument doc = JsonDocument.Parse(await response.Content.ReadAsStringAsync());

        Assert.Equal(HttpStatusCode.OK, response.StatusCode);
        Assert.Equal("Healthy", doc.RootElement.GetProperty("status").GetString());
    }

    [Fact]
    public async Task UnhandledExceptionInRequest_MakesHealthDegraded()
    {
        await using HealthTestHost host = HealthTestHost.Create();

        // /throw triggers a real unhandled exception through FaultTrackingMiddleware — the exact
        // same code path a genuinely-broken MCP tool call or any other request would hit, not a
        // test-only injection hook.
        await Assert.ThrowsAnyAsync<Exception>(() => host.Client.GetAsync("/throw"));

        Assert.True(host.FaultTracker.HasRecentFault);
        Assert.Equal("simulated tool failure", host.FaultTracker.LastFaultMessage);

        using HttpResponseMessage healthResponse = await host.Client.GetAsync("/health");
        JsonDocument doc = JsonDocument.Parse(await healthResponse.Content.ReadAsStringAsync());

        Assert.Equal("Degraded", doc.RootElement.GetProperty("status").GetString());

        JsonElement faultCheck = doc.RootElement.GetProperty("checks").EnumerateArray()
            .Single(c => c.GetProperty("name").GetString() == "unhandled-fault");
        Assert.Equal("Degraded", faultCheck.GetProperty("status").GetString());
        Assert.Contains("simulated tool failure", faultCheck.GetProperty("description").GetString());

        // Fault tracking is untagged (not "ready"), so /health/ready must stay unaffected.
        using HttpResponseMessage readyResponse = await host.Client.GetAsync("/health/ready");
        JsonDocument readyDoc = JsonDocument.Parse(await readyResponse.Content.ReadAsStringAsync());
        Assert.Equal("Healthy", readyDoc.RootElement.GetProperty("status").GetString());
        Assert.Empty(readyDoc.RootElement.GetProperty("checks").EnumerateArray());
    }

    [Fact]
    public async Task FailingSelfTestCheck_MakesHealthDegraded_WithoutAffectingHealthReady()
    {
        await using HealthTestHost host = HealthTestHost.Create();
        host.SelfTestCheck.ExtraChecks.Add(("always-fails", () => false));

        using HttpResponseMessage healthResponse = await host.Client.GetAsync("/health");
        JsonDocument doc = JsonDocument.Parse(await healthResponse.Content.ReadAsStringAsync());

        Assert.Equal("Degraded", doc.RootElement.GetProperty("status").GetString());
        JsonElement selfTestCheck = doc.RootElement.GetProperty("checks").EnumerateArray()
            .Single(c => c.GetProperty("name").GetString() == "self-test");
        Assert.Equal("Degraded", selfTestCheck.GetProperty("status").GetString());

        using HttpResponseMessage readyResponse = await host.Client.GetAsync("/health/ready");
        JsonDocument readyDoc = JsonDocument.Parse(await readyResponse.Content.ReadAsStringAsync());
        Assert.Equal("Healthy", readyDoc.RootElement.GetProperty("status").GetString());
    }

    [Fact]
    public async Task SelfTestCheck_ThrowingException_IsCaughtAndReportedAsDegraded()
    {
        await using HealthTestHost host = HealthTestHost.Create();
        host.SelfTestCheck.ExtraChecks.Add(("throws", () => throw new InvalidOperationException("boom")));

        using HttpResponseMessage response = await host.Client.GetAsync("/health");

        // A throwing self-test check must not itself surface as a 500 to the /health caller.
        Assert.Equal(HttpStatusCode.OK, response.StatusCode);
        JsonDocument doc = JsonDocument.Parse(await response.Content.ReadAsStringAsync());
        Assert.Equal("Degraded", doc.RootElement.GetProperty("status").GetString());
    }

    [Fact]
    public async Task FaultTracker_ClearFault_RestoresHealthyStatus()
    {
        await using HealthTestHost host = HealthTestHost.Create();
        host.FaultTracker.RecordFault(new InvalidOperationException("temporary"));

        using (HttpResponseMessage degraded = await host.Client.GetAsync("/health"))
        {
            JsonDocument degradedDoc = JsonDocument.Parse(await degraded.Content.ReadAsStringAsync());
            Assert.Equal("Degraded", degradedDoc.RootElement.GetProperty("status").GetString());
        }

        host.FaultTracker.ClearFault();

        using HttpResponseMessage healthy = await host.Client.GetAsync("/health");
        JsonDocument healthyDoc = JsonDocument.Parse(await healthy.Content.ReadAsStringAsync());
        Assert.Equal("Healthy", healthyDoc.RootElement.GetProperty("status").GetString());
    }
}

internal sealed class HealthTestHost : IAsyncDisposable
{
    public TestServer Server { get; }
    public HttpClient Client { get; }
    public UnhandledFaultTracker FaultTracker { get; }
    public SelfTestHealthCheck SelfTestCheck { get; }

    private HealthTestHost(TestServer server)
    {
        Server = server;
        Client = server.CreateClient();
        FaultTracker = server.Services.GetRequiredService<UnhandledFaultTracker>();

        // Resolved as the concrete singleton type directly (not via GetServices<IHealthCheck>() —
        // AddCheck<T> wraps checks in HealthCheckRegistration objects rather than exposing them
        // as resolvable IHealthCheck services), which is exactly the same instance AddCheck<T>
        // picked up via ActivatorUtilities.GetServiceOrCreateInstance in Create() below.
        SelfTestCheck = server.Services.GetRequiredService<SelfTestHealthCheck>();
    }

    public static HealthTestHost Create()
    {
        IWebHostBuilder builder = new WebHostBuilder()
            .UseTestServer()
            .ConfigureServices(services =>
            {
                services.AddLogging(l => l.ClearProviders());
                services.AddSingleton<IOptions<TokenSaverConfig>>(
                    Microsoft.Extensions.Options.Options.Create(new TokenSaverConfig()));
                services.AddSingleton<OllamaEndpointRegistry>();
                services.AddSingleton<UnhandledFaultTracker>();

                // Registered as singletons ourselves (rather than relying on AddHealthChecks()
                // .AddCheck<T>()'s default transient-or-existing resolution) so the exact same
                // instance the health check middleware queries is also the one HealthTestHost's
                // constructor resolves to mutate SelfTestHealthCheck.ExtraChecks — a second,
                // separately-constructed instance would silently ignore that mutation.
                services.AddSingleton<UnhandledFaultHealthCheck>();
                services.AddSingleton<SelfTestHealthCheck>();

                services.AddRouting();

                services.AddHealthChecks()
                    .AddCheck<UnhandledFaultHealthCheck>("unhandled-fault")
                    .AddCheck<SelfTestHealthCheck>("self-test");
            })
            .Configure(app =>
            {
                app.UseMiddleware<FaultTrackingMiddleware>();

                app.Map("/throw", branch => branch.Run(_ => Task.FromException(new InvalidOperationException("simulated tool failure"))));

                app.UseRouting();
                app.UseEndpoints(endpoints =>
                {
                    // Same JSON ResponseWriter Program.cs uses for both routes, so tests parse
                    // the exact shape a real client sees rather than the framework's bare
                    // plaintext default.
                    endpoints.MapHealthChecks("/health", new HealthCheckOptions
                    {
                        ResponseWriter = WriteJsonHealthResponse
                    });
                    endpoints.MapHealthChecks("/health/ready", new HealthCheckOptions
                    {
                        Predicate = check => check.Tags.Contains("ready"),
                        ResponseWriter = WriteJsonHealthResponse
                    });
                });
            });

        TestServer server = new(builder);
        return new HealthTestHost(server);
    }

    // Mirrors Program.cs's WriteJsonHealthResponse exactly, so tests exercise the same response
    // shape a real client gets rather than a parallel reimplementation of it.
    private static async Task WriteJsonHealthResponse(HttpContext ctx, HealthReport report)
    {
        ctx.Response.ContentType = "application/json";
        var result = new
        {
            status = report.Status.ToString(),
            checks = report.Entries.Select(e => new
            {
                name = e.Key,
                status = e.Value.Status.ToString(),
                description = e.Value.Description,
                error = e.Value.Exception?.Message,
                data = e.Value.Data.Count > 0 ? e.Value.Data : null
            }),
            totalDuration = report.TotalDuration.TotalMilliseconds
        };
        await ctx.Response.WriteAsJsonAsync(result);
    }

    public async ValueTask DisposeAsync()
    {
        Client.Dispose();
        Server.Dispose();
        await ValueTask.CompletedTask;
    }
}

public class TokenEconomyToolsTests
{
    private static TokenEconomyTools CreateTools(TokenSaverConfig? config = null)
    {
        TokenSaverConfig cfg = config ?? new TokenSaverConfig();
        HttpClient httpClient = new() { BaseAddress = new Uri("http://localhost:1") };
        OllamaService ollama = new(httpClient, Options.Create(cfg), NullLogger<OllamaService>.Instance);
        ModelRouteResolver modelRoutes = new(Options.Create(cfg));
        SavingsTracker savings = new(new TokenEconomyDbAccessor(), Options.Create(cfg));
        DistillationService distill = new(ollama, modelRoutes, savings, Options.Create(cfg));
        return new TokenEconomyTools(distill, savings, modelRoutes, ollama, Options.Create(cfg));
    }

    [Fact]
    public void TokenBudget_UnderThreshold_ReportsNotOverBudget()
    {
        TokenEconomyTools tools = CreateTools();

        string json = tools.TokenBudget("short content", threshold: 8000);
        JsonElement result = JsonDocument.Parse(json).RootElement;

        Assert.False(result.GetProperty("over_budget").GetBoolean());
        Assert.Equal(8000, result.GetProperty("threshold").GetInt32());
    }

    [Fact]
    public void TokenBudget_OverThreshold_ReportsOverBudgetWithCorrectPct()
    {
        TokenEconomyTools tools = CreateTools();
        string content = new string('a', 4000); // ~1000 estimated tokens

        string json = tools.TokenBudget(content, threshold: 500);
        JsonElement result = JsonDocument.Parse(json).RootElement;

        Assert.True(result.GetProperty("over_budget").GetBoolean());
        Assert.Equal(1000, result.GetProperty("tokens").GetInt32());
        Assert.Equal(200, result.GetProperty("pct_of_threshold").GetInt32()); // 1000/500 = 200%
    }

    [Fact]
    public void TokenBudget_ZeroThreshold_DoesNotDivideByZero()
    {
        TokenEconomyTools tools = CreateTools();

        string json = tools.TokenBudget("anything", threshold: 0);
        JsonElement result = JsonDocument.Parse(json).RootElement;

        Assert.Equal(0, result.GetProperty("pct_of_threshold").GetInt32());
    }
}
